import React from 'react';

const Terms = () => {
  return (
    <div className="pg" id="page-terms">
      <div className="legal">
        <h1>Terms of Service</h1>
        <p>Last updated: December 2024</p>

        <h2>Acceptance of Terms</h2>
        <p>By accessing and using Clarix services, you accept and agree to be bound by the terms and provision of this agreement.</p>

        <h2>Services</h2>
        <p>Clarix provides AI consulting, automation, and related services. We reserve the right to modify or discontinue services at any time.</p>

        <h2>User Responsibilities</h2>
        <p>You agree to provide accurate information and use our services in compliance with applicable laws and regulations.</p>

        <h2>Intellectual Property</h2>
        <p>All content, features, and functionality of our services are owned by Clarix and are protected by copyright, trademark, and other intellectual property laws.</p>

        <h2>Limitation of Liability</h2>
        <p>Clarix shall not be liable for any indirect, incidental, special, or consequential damages arising out of or in connection with the use of our services.</p>

        <h2>Contact Information</h2>
        <p>For questions about these Terms, please contact us at kottapalli.deepakvarma2005@gmail.com</p>

        <div className="ldate">Last updated: December 15, 2024</div>
      </div>
    </div>
  );
};

export default Terms;
